const MS_PER_DAY = 24 * 60 * 60 * 1000;

/** Retirements at or before this instant have already been released. */
function retirementCutoff(now: Date): string {
  return toIsoTimestamp(new Date(now.getTime() - ORG_SLUG_HOLD_DAYS * MS_PER_DAY));
}

export async function findOrgById(orgId: OrgId): Promise<Organization | null> {
  const row = getDb()
    .select()
    .from(organizations)
    .where(eq(organizations.id, orgId))
    .get();
  return row ? toOrganization(row) : null;
}

export async function findOrgBySlug(slug: string): Promise<Organization | null> {
  const db = getDb();
  const now = new Date();
  const row = db
    .select()
    .from(organizations)
    .where(and(eq(organizations.slug, slug), isNull(organizations.archivedAt)))
    .get();
  if (row) return toOrganization(row);

  const retired = db
    .select({ org: organizations })
    .from(retiredOrganizationSlugs)
    .innerJoin(organizations, eq(organizations.id, retiredOrganizationSlugs.orgId))
    .where(
      and(
        eq(retiredOrganizationSlugs.slug, slug),
        gt(retiredOrganizationSlugs.retiredAt, retirementCutoff(now)),
        isNull(organizations.archivedAt),
      ),
    )
    .get();
  return retired ? toOrganization(retired.org) : null;
}

/** Every org the user still holds a live membership in. */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Derives and inserts the slug in one write transaction, including held slugs
 * in the collision set so creation cannot claim a still-usable old URL.
 */
export async function insertOrg(
  input: CreateOrganizationInput,
  ownerId: UserId,
): Promise<Organization> {
  return getDb().transaction((tx) => {
    const now = new Date();
    const slug = uniqueSlug(input.slug, takenOrgSlugs(tx, input.slug, now));
    const stamp = toIsoTimestamp(now);

    const row = tx
      .insert(organizations)
      .values({
        id: newId(),
        name: input.name,
        slug,
        ownerId,
        plan: input.plan,
        logoUrl: null,
        trialEndsAt: null,
        createdAt: stamp,
        updatedAt: stamp,
      })
      .returning()
      .get();

    return toOrganization(row);
  }, { behavior: "immediate" });
}

/** Settings and profile patch. URL changes go through `renameOrgSlug`. */
export async function updateOrg(
  orgId: OrgId,
  patch: UpdateOrganizationInput,
): Promise<Organization> {
  const current = await findOrgById(orgId);
  if (!current) throw new Error(`Organization ${orgId} not found`);

  const settings = { ...current.settings, ...(patch.settings ?? {}) };

  const row = getDb()
    .update(organizations)
    .set({
      ...(patch.name === undefined ? {} : { name: patch.name }),
      ...(patch.logoUrl === undefined ? {} : { logoUrl: patch.logoUrl }),
      defaultIssueStatus: settings.defaultIssueStatus,
      allowPublicProjects: settings.allowPublicProjects,
      requireTwoFactor: settings.requireTwoFactor,
      digestHourUtc: settings.digestHourUtc,
      enabledFlagOverrides: JSON.stringify(settings.enabledFlagOverrides),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  return toOrganization(row);
}

/** Checks the chosen URL and swaps its retirement atomically with the slug. */
export async function renameOrgSlug(
  orgId: OrgId,
  slug: string,
): Promise<{ organization: Organization; from: string } | null> {
  return getDb().transaction((tx) => {
    const current = tx
      .select()
      .from(organizations)
      .where(eq(organizations.id, orgId))
      .get();
    if (!current) return null;
    if (current.slug === slug) {
      return { organization: toOrganization(current), from: current.slug };
    }

    const now = new Date();
    const taken = tx
      .select({ id: organizations.id })
      .from(organizations)
      .where(and(eq(organizations.slug, slug), ne(organizations.id, orgId)))
      .get();
    const held = tx
      .select({ slug: retiredOrganizationSlugs.slug })
      .from(retiredOrganizationSlugs)
      .where(
        and(
          eq(retiredOrganizationSlugs.slug, slug),
          ne(retiredOrganizationSlugs.orgId, orgId),
          gt(retiredOrganizationSlugs.retiredAt, retirementCutoff(now)),
        ),
      )
      .get();
    if (taken || held) throw new InvalidSlugError(slug, "is unavailable");

    const stamp = toIsoTimestamp(now);
    // Reclaiming an old URL ends its retirement, including any expired hold.
    tx.delete(retiredOrganizationSlugs)
      .where(eq(retiredOrganizationSlugs.slug, slug))
      .run();
    tx.insert(retiredOrganizationSlugs)
      .values({ slug: current.slug, orgId, retiredAt: stamp })
      .onConflictDoUpdate({
        target: retiredOrganizationSlugs.slug,
        set: { orgId, retiredAt: stamp },
      })
      .run();

    const row = tx
      .update(organizations)
      .set({ slug, updatedAt: stamp })
      .where(eq(organizations.id, orgId))
      .returning()
      .get();

    return { organization: toOrganization(row), from: current.slug };
  }, { behavior: "immediate" });
}

export async function archiveOrg(orgId: OrgId): Promise<Organization> {
  const row = getDb()
    .update(organizations)
    .set(archivePatch())
    .where(eq(organizations.id, orgId))
    .returning()
    .get();

  if (!row) throw new Error(`Organization ${orgId} not found`);
  return toOrganization(row);
}

/** Feeds `uniqueSlug()`; matching on the prefix keeps the scan small. */
export async function listTakenOrgSlugs(
  prefix: string,
): Promise<readonly string[]> {
  return takenOrgSlugs(getDb(), prefix, new Date());
}

function takenOrgSlugs(
  db: Pick<Db, "select">,
  prefix: string,
  now: Date,
): readonly string[] {
  const rows = db
    .select({ slug: organizations.slug })
    .from(organizations)
    .where(like(organizations.slug, `${prefix}%`))
    .all();
  const retired = db
    .select({ slug: retiredOrganizationSlugs.slug })
    .from(retiredOrganizationSlugs)
    .where(
      and(
        like(retiredOrganizationSlugs.slug, `${prefix}%`),
        gt(retiredOrganizationSlugs.retiredAt, retirementCutoff(now)),
      ),
    )
    .all();
  return [...rows, ...retired].map((row) => row.slug);
}
